INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources)
VALUES
  ('236fb3c1-b473-407f-b8a0-d76039b28087', 'c1ac1330-47f7-44ec-baf3-c913d926b97c', 'Official Cambridge city council profile lists "Universal childcare" as a key stated policy priority. Al-Zubi is a DSA-aligned Democratic Socialist who has consistently framed public services as rights. The explicit use of "universal" childcare aligns with stance 1 (publicly funded universal access).', '{}'),
  ('236fb3c1-b473-407f-b8a0-d76039b28087', '4938766b-b45a-46e3-93bd-b8b30651271a', 'Al-Zubi''s official profile and council record show strong support for expanding the municipal housing program and launching a social housing pilot to keep people housed. She co-sponsored a motion to study shelter expansion at 240 Albany St (passed unanimously, Dec 2025). Her housing-as-human-right framing (DSA) aligns with stance 2: decriminalize public sleeping, invest in shelter and services. No direct camping-ban enforcement votes found.', '{}'),
  ('236fb3c1-b473-407f-b8a0-d76039b28087', '6fbf39ae-6b19-4182-b4c2-6a8d25c86c0f', 'Al-Zubi champions social housing as the primary homelessness solution and supported unanimous council action to expand shelter facilities. As a DSA member who frames housing as a right, her approach emphasizes shelter capacity and services rather than enforcement. Aligns with stance 2: expand shelter capacity and services as the primary strategy, using enforcement only after services are offered.', '{}'),
  ('236fb3c1-b473-407f-b8a0-d76039b28087', '4e2c69ce-591e-4197-9cd5-7aceff79d390', 'Al-Zubi voted unanimously to ban ICE operations on city property, prohibit city staff from assisting ICE, and block access to immigration status information (Feb 2026). She proposed expanding the hiring ban to cover all former ICE/DHS/CBP agents regardless of when they served, calling current agents involved in "murderous, illegal operations." Cambridge maintains sanctuary city policy. Aligns with stance 2: significantly expand legal pathways and easy access.', '{}'),
  ('236fb3c1-b473-407f-b8a0-d76039b28087', '44905f3b-e105-4f6c-afc7-5d223813dbac', 'Al-Zubi co-sponsored the comprehensive ICE non-cooperation ordinance and led the amendment to bar hiring all former ICE/HSI/CBP agents, stating agents from prior administrations "remain actively involved in these murderous, illegal operations." Cambridge Police already decline ICE information requests per sanctuary policy. She supports compliance only with court-ordered warrants — aligns with stance 2: deport only serious violent criminals, provide legal status to others.', '{}'),
  ('236fb3c1-b473-407f-b8a0-d76039b28087', 'e9ebefcd-c496-45e8-b816-a79f8442ba85', 'As chair of the Cambridge Public Safety Committee, Al-Zubi introduced a policy order to end ShotSpotter use within 90 days (May 2026), citing data-sharing risks: "the question becomes not who does ShotSpotter share data with, but who can ShotSpotter share data with." She represents a reform-oriented approach to policing aligned with stance 2: maintain current police staffing but shift surveillance/non-violent approaches, support mental health co-responders.', '{}'),
  ('236fb3c1-b473-407f-b8a0-d76039b28087', 'c308e8e8-caac-44f5-ab04-dbfecf40bbe2', 'Al-Zubi is a renter and self-described Democratic Socialist who advocates for housing as a human right and launched a social housing pilot effort. She aligned with Sobrinho-Wheeler (DSA) on affordable housing measures. Cambridge already has strong tenant protections; her platform focuses on expanding affordable stock through social housing. Her strong tenant-protection framing aligns with stance 2: strengthen existing rent stabilization and extend coverage to more units.', '{}'),
  ('236fb3c1-b473-407f-b8a0-d76039b28087', 'c5ab4eab-702f-49b8-9277-8ea53f3835c6', 'Al-Zubi co-sponsored a March 2026 policy order requiring gender-neutral single-stall bathrooms in all new public spaces, co-sponsoring during the meeting to add her name. As a progressive Democratic Socialist she has consistently supported LGBTQ+ inclusive policies. Aligns with stance 1: require all states to recognize same-sex marriage with full federal benefits and protections.', '{}'),
  ('236fb3c1-b473-407f-b8a0-d76039b28087', 'f1e44d66-5d27-4b51-b54f-b7ace86f6a3c', 'Al-Zubi backed Cambridge''s Green New Deal progress on her 2023 campaign and endorsed bike infrastructure as essential for safety ("Bike infrastructure saves lives. It''s that simple"). She received Cambridge Bicycle Safety''s endorsement as a "bike champion." The council''s zero emissions transportation plan (voted 2024) aligns with her stated positions. Aligns with stance 2: rapidly transition to renewable energy and phase out fossil fuels.', '{}'),
  ('236fb3c1-b473-407f-b8a0-d76039b28087', '4559b513-0fd8-4ed1-babd-f3b554162f40', 'Al-Zubi was part of the unanimous Cambridge City Council vote (April 2026) requesting the city manager study regulatory approaches to data center expansion, driven by concerns about grid capacity and water use. No individual statement from Al-Zubi on data centers was found. The unanimous-study posture aligns with stance 3: allow development with impact assessments and cost-sharing agreements before approval.', '{}'),
  ('d2358e54-6860-4382-8c8d-95a3dabea874', 'c1ac1330-47f7-44ec-baf3-c913d926b97c', 'Azeem''s official city council page credits him with playing a key role in establishing universal pre-K for all Cambridge residents — publicly funded universal childcare with no income restriction. His third-term priority is affordability for all residents.', '{}'),
  ('d2358e54-6860-4382-8c8d-95a3dabea874', 'f1e44d66-5d27-4b51-b54f-b7ace86f6a3c', 'Direct quote from 2023 campaign materials: ''Housing policy is climate policy. We need to build more housing and greener housing. This means reforming out-of-touch policies so that green, smart housing can be built without sacrificing the essence of Cambridge.'' He advocates for transit-oriented development and walkable cities as climate tools — aligns with investing in clean energy and sustainability while not endorsing an emergency declaration or rapid fossil fuel phase-out.', '{}'),
  ('d2358e54-6860-4382-8c8d-95a3dabea874', '4559b513-0fd8-4ed1-babd-f3b554162f40', 'In April 2026 Azeem voted unanimously to request the city manager prepare a regulatory report on data centers — an investigative/impact assessment approach. He simultaneously cautioned against blanket opposition, saying data centers fill important urban functions in vacant commercial space: ''Would we rather wait until those fill up with more offices and labs, or do we want data centers to fill in there? I think this policy order is fundamentally right, which is just an investigation.'' Aligns with stance 3: allow with impact assessments and community benefit review before approval.', '{}'),
  ('d2358e54-6860-4382-8c8d-95a3dabea874', '44905f3b-e105-4f6c-afc7-5d223813dbac', 'Azeem voted as part of a unanimous Cambridge City Council to ban ICE operations on city property and bar the city from sharing immigration status information with federal agencies (Feb 2026). He also supported legal counsel for undocumented immigrants early in his tenure and expressed concern about surveillance technology being used against undocumented residents. Aligns with deportation only for serious violent criminals while providing legal status to others.', '{}'),
  ('d2358e54-6860-4382-8c8d-95a3dabea874', '4e2c69ce-591e-4197-9cd5-7aceff79d390', 'Azeem supported legal counsel for undocumented immigrants, voted unanimously to ban ICE operations on Cambridge city property and prohibit city employees from sharing immigration status with federal agencies (Feb 2026), and expressed specific concern about police surveillance technology being chilling to undocumented residents. Cambridge is an official sanctuary city. Aligns with significantly increasing legal pathways and easy pathways to citizenship.', '{}'),
  ('d2358e54-6860-4382-8c8d-95a3dabea874', '4938766b-b45a-46e3-93bd-b8b30651271a', 'Azeem''s public safety platform explicitly includes creating an unarmed public safety response to replace certain police functions — including non-violent and social service calls. He voted as part of the Cambridge progressive majority for services-first homelessness approaches. No evidence of support for criminalizing public sleeping or camping. Aligns with decriminalizing public sleeping while investing in shelter and outreach.', '{}'),
  ('34da113e-e5dc-4637-9be1-9d42a6feea93', '7687de4f-4d0b-462a-b803-bdfb23b16b42', 'Flaherty expressed enthusiasm for the 2026 ''snow corps'' proposal to engage young people in neighborhood sidewalk clearing, stating: ''If this policy order incentivizes and encourages young people to get back to walking around the neighborhood with a shovel on their shoulder, and shoveling out their neighbor''s sidewalks and crosswalks, I''m all for it.'' This reflects a community-engaged expansion of sanitation services over privatization or pure enforcement. Also voted against a majority-backed parking-pass fee increase (March 2026), suggesting skepticism of fee-based approaches that burden residents. Source: https://www.cambridgeday.com/2026/03/06/city-council-snow-corps/', '{}'),
  ('34da113e-e5dc-4637-9be1-9d42a6feea93', 'eb3d1247-0de1-4b7f-baec-7259861efd53', 'Flaherty supports targeted economic development tools with community-benefit conditions rather than blanket incentives. On the real estate transfer fee (March 2026), he moved to shift the burden from sellers to buyers and stated the fee is worthwhile: ''If it serves as a block to developers buying up homes for the purpose of demolishing them and constructing apartments with zero affordability requirements, then I''m in favor of it.'' He also supports financial incentives specifically for office-to-residential conversion rather than broad corporate tax abatements. This aligns with stance 3: targeted incentives with community benefit requirements before approval. Source: https://www.cambridgeday.com/2026/03/04/cambridge-real-estate-fee/', '{}'),
  ('34da113e-e5dc-4637-9be1-9d42a6feea93', 'c267e137-0ff9-4e7d-9d13-e3cea1756cd0', 'Flaherty''s signature policy is a citywide youth violence reduction program for ages 16-24 using Cognitive Behavioral Therapy and mental health approaches, explicitly framed as an alternative to incarceration. He has stated the goal is to ''reduce incarceration, sustain employment, and improve parenting.'' As a 30-year criminal defense attorney he has consistently argued for treatment and diversion over detention. This aligns with stance 2: reducing incarceration through diversion, bail reform, and treatment alternatives rather than building new capacity. Source: https://www.cambridgeday.com/2025/10/30/cambridge-city-council-election-guide-2025/', '{}'),
  ('a8f48816-2ebc-4ae4-9667-a12d4c18f5ec', '4938766b-b45a-46e3-93bd-b8b30651271a', 'McGovern co-sponsored the policy order to renovate Cambridge''s Albany St. homeless shelter (240 Albany), calling conditions not dignified for anybody" (Feb 2026). As mayor in 2021 he cited $12M spent on homeless services and advocated keeping the non-congregate Green Hall shelter open. His 30-year social-work background shapes a service-first', '{}'),
  ('a8f48816-2ebc-4ae4-9667-a12d4c18f5ec', '4e2c69ce-591e-4197-9cd5-7aceff79d390', 'In Feb 2026 McGovern voted for Cambridge orders banning ICE from municipal property and prohibiting city cooperation with immigration enforcement. He stated: There are some things we''re limited to doing... But where we can', '{}'),
  ('a8f48816-2ebc-4ae4-9667-a12d4c18f5ec', '44905f3b-e105-4f6c-afc7-5d223813dbac', 'McGovern''s voting record on ICE cooperation (Feb 2026) reflects a policy of protecting all residents regardless of status — banning ICE on city property and prohibiting police cooperation with immigration holds. Consistent with only deporting serious violent criminals while protecting most undocumented residents.', '{}'),
  ('a8f48816-2ebc-4ae4-9667-a12d4c18f5ec', 'c5ab4eab-702f-49b8-9277-8ea53f3835c6', 'McGovern authored a December 2020 council condemnation of homophobic bullying and intimidation anywhere in the city" after an incident involving an LGBTQ+ resident. In March 2026 he led the unanimous passage of gender-neutral bathroom requirements', '{}'),
  ('a8f48816-2ebc-4ae4-9667-a12d4c18f5ec', 'd1618b9c-0b9e-45af-b986-bb33d270b8e4', 'McGovern sponsored and secured unanimous passage of Cambridge''s gender-neutral bathroom ordinance in March 2026, explicitly noting: In the climate that we''re in today', '{}'),
  ('a8f48816-2ebc-4ae4-9667-a12d4c18f5ec', '4559b513-0fd8-4ed1-babd-f3b554162f40', 'Cambridge City Council voted unanimously in April 2026 to request a city manager report on regulating data center expansion, citing grid constraints and environmental impacts including water consumption. McGovern voted with the unanimous council majority. Councillor Nolan (co-sponsor) framed it as preventing grid strain on residential ratepayers — aligning with requiring data centers to fund their own dedicated capacity.', '{}'),
  ('a8f48816-2ebc-4ae4-9667-a12d4c18f5ec', '92730f69-ae57-401c-8ad1-2d07834a895d', 'McGovern questioned selective campaign finance restrictions targeting only real estate developers, asking: If this is really about looking holistically at anybody doing business with the city', '{}'),
  ('a8f48816-2ebc-4ae4-9667-a12d4c18f5ec', 'c1ac1330-47f7-44ec-baf3-c913d926b97c', 'McGovern''s 2013 campaign platform centered on expansion of affordable early childhood education" as a top priority. His official Cambridge city council profile cites income insecurity and vulnerable families as core focuses. His 30-year background as a social worker serving at-risk children and families reinforces a position favoring significant expansion of childcare subsidies and provider support."', '{}'),
  ('a8f48816-2ebc-4ae4-9667-a12d4c18f5ec', '7687de4f-4d0b-462a-b803-bdfb23b16b42', 'McGovern co-sponsored the snow corps exploration order (March 2026) to have the city take responsibility for public sidewalk clearing, acknowledging the current system isn''t working." He co-sponsored the order to renovate the Albany St. shelter due to deteriorating conditions. His approach favors expanding city sanitation staffing and services', '{}'),
  ('a8f48816-2ebc-4ae4-9667-a12d4c18f5ec', '1935979c-b290-42e4-baa5-8cb0138b4ffa', 'McGovern voted (as part of the unanimous council) for the upzoning compromise on Cambridge Street (Jan 2026), favoring development with height limits. He said: It is not the leap forward that I think we need if we''re going to address our housing shortage. But it is better to pass this than to not pass this." Reflects balancing development with environmental standards — consistent environmental standards without blocking growth."', '{}'),
  ('eeaaf186-3dc4-4ae3-b28f-6a0a0d54c585', 'f1e44d66-5d27-4b51-b54f-b7ace86f6a3c', 'Her 2019 campaign platform explicitly called for ''no new gas lines for any new construction'' and a city-funded solar installation program, with costs recouped at home sale. She was endorsed by the Sierra Club and described in 2021 Cambridge Residents Alliance endorsement materials as having ''a history of climate activism.'' Source: cambridgeday.com/2025/10/patty-nolan/ and cambridgeday.com/2021/10/31/residents-alliance-endorses-seven-for-council/', '{}'),
  ('eeaaf186-3dc4-4ae3-b28f-6a0a0d54c585', 'a22215c3-6693-4bc2-b248-01aebba14570', 'Nolan''s 2019 platform included explicitly banning gas lines in all new construction and eliminating fossil fuel infrastructure citywide. She proposed city-funded solar on residential properties to accelerate transition. This directly aligns with stopping new fossil fuel permits/infrastructure. Source: cambridgeday.com/2025/10/patty-nolan/ (2019 platform recap)', '{}'),
  ('eeaaf186-3dc4-4ae3-b28f-6a0a0d54c585', 'b9ccee94-ad96-4f10-b655-889d8e5abe92', 'At the January 28, 2026 council meeting, Nolan stated: ''We will not interfere with the federal immigration work. However, when our own laws are broken, I think we need to proactively think about how do we ensure that our law enforcement can enforce law and order when the laws are being broken by federal officials.'' She also voted unanimously in February 2026 to codify banning ICE from city municipal property. Her framing was accountability-focused rather than sanctuary-first. Source: cambridgeday.com/2026/01/28/city-prepares-for-ice/ and cambridgeday.com/2026/02/11/city-council-ice-response/', '{}'),
  ('eeaaf186-3dc4-4ae3-b28f-6a0a0d54c585', '0bc588c6-39e1-4084-b5de-cac909b8b762', 'The 2021 Cambridge Residents Alliance endorsement (which included Nolan) explicitly committed to ''uphold human rights through community-led public safety programs'' and supported the HEART alternative public safety initiative — a non-police crisis response model. She co-sponsored the March 2026 gender-neutral bathrooms order, which passed unanimously. Her record and endorsements consistently align with progressive civil rights enforcement. Source: cambridgeday.com/2021/10/31/residents-alliance-endorses-seven-for-council/ and cambridgeday.com/2026/03/24/future-bathrooms-gender-neutral/', '{}'),
  ('eeaaf186-3dc4-4ae3-b28f-6a0a0d54c585', '4938766b-b45a-46e3-93bd-b8b30651271a', 'In February 2021, Nolan voted with the 7-member council majority to explore converting Green Hall dormitory for homeless housing, leveraging 100% federal reimbursement under Biden''s policy. She postponed (not blocked) debate on hostile architecture — anti-homeless design features — suggesting a services-first rather than enforcement-first orientation. Her endorsement by the Cambridge Residents Alliance included commitments to humane public safety approaches. Source: cambridgeday.com/2021/02/04/city-could-keep-homeless-shelter-in-empty-dorm-after-current-contract-with-state-ends-in-spring/', '{}'),
  ('eeaaf186-3dc4-4ae3-b28f-6a0a0d54c585', 'c267e137-0ff9-4e7d-9d13-e3cea1756cd0', 'Nolan''s 2021 Cambridge Residents Alliance endorsement explicitly supported the HEART (Holistic Emergency Alternative Response Team) initiative — a community-led public safety program that redirects funds from policing toward mental health, social work, and alternatives to incarceration. She was part of the endorsed slate that committed to ''community-led public safety programs'' rather than expanding traditional enforcement capacity. Source: cambridgeday.com/2021/10/31/residents-alliance-endorses-seven-for-council/', '{}'),
  ('cc61015f-dba2-4f52-9f1f-832ef23f6595', '4e2c69ce-591e-4197-9cd5-7aceff79d390', 'As mayor Siddiqui increased city funding for legal service providers for immigrants and supported Know Your Rights trainings. Cambridge maintains sanctuary status with police having declined ICE cooperation at least 6 times. She is a first-generation immigrant herself (Pakistani-born) and her official bio highlights immigrant support as a priority. Aligns with significantly expanding legal pathways while protecting residents. Source: https://www.cambridgema.gov/Departments/citycouncil/members/sumbulsiddiqui', '{}'),
  ('cc61015f-dba2-4f52-9f1f-832ef23f6595', '44905f3b-e105-4f6c-afc7-5d223813dbac', 'Cambridge police declined ICE cooperation at least 6 times per Jan 2026 Cambridge Day reporting. As mayor Siddiqui oversaw city codifying its non-cooperation policy with ICE in Feb 2026. She funded legal services for detained immigrants and Know Your Rights training. The city council (with Siddiqui as mayor) proposed immigration emergency hotlines and family stabilization programs. Consistent with deporting only serious violent offenders while protecting others. Source: https://www.cambridgeday.com/2026/01/28/city-prepares-for-ice/', '{}'),
  ('cc61015f-dba2-4f52-9f1f-832ef23f6595', '4938766b-b45a-46e3-93bd-b8b30651271a', 'As mayor Siddiqui appointed an ad hoc working group on homelessness (2021) and advocated for non-congregate shelters. Her administration supported keeping a Cambridge homeless shelter in an empty university dorm rather than closing it. City Hall 2026 priorities under her leadership included addressing unhoused visitors through outreach and services. Consistent with decriminalizing public sleeping while investing in shelter capacity and voluntary service connections. Source: https://www.cambridgema.gov/Departments/citycouncil/members/sumbulsiddiqui; https://en.wikipedia.org/wiki/Sumbul_Siddiqui', '{}'),
  ('cc61015f-dba2-4f52-9f1f-832ef23f6595', 'c1ac1330-47f7-44ec-baf3-c913d926b97c', 'Siddiqui spearheaded the Cambridge Preschool Program providing free preschool to all eligible Cambridge four-year-olds (universal, not means-tested). She also launched Rise Up Cambridge providing $500/month to approximately 2,000 families with ARPA funds, and an Early College Program enabling free college credit for high schoolers. The breadth of these universal childcare and economic support programs aligns with publicly funded universal childcare regardless of income. Source: https://www.cambridgema.gov/Departments/citycouncil/members/sumbulsiddiqui', '{}'),
  ('cc61015f-dba2-4f52-9f1f-832ef23f6595', 'f1e44d66-5d27-4b51-b54f-b7ace86f6a3c', 'Siddiqui convened a climate crisis task force as mayor and listed climate change alongside gun violence as a key challenge in her 2022 inaugural address. The 2026 Cambridge City Council priorities (adopted Feb 9, 2026 under her chairmanship) include Sustainability and Climate Resilience as one of five priority areas. No specific ban on fossil fuels or emergency declaration found; approach is investment and planning-based. Consistent with investing in clean energy while gradually reducing fossil fuel reliance. Source: https://www.cambridgema.gov/Departments/citycouncil; https://www.cambridgeday.com/2022/01/03/city-councillors-hold-chilly-outdoor-inaugural-quickly-reelecting-siddiqui-and-mallon-to-lead/', '{}'),
  ('cc61015f-dba2-4f52-9f1f-832ef23f6595', '92730f69-ae57-401c-8ad1-2d07834a895d', 'While mayor in December 2021 Cambridge passed campaign finance reform limiting contributions from individuals or entities doing business with the city to $200 per candidate annually, stricter than the state limit of $1,000. In 2025 Siddiqui''s council co-sponsored public funding research (funded elections policy order). These actions align with strictly limiting corporate donations and dark money. Source: https://www.cambridgeday.com/2025/10/18/coming-to-cambridge-city-council-utility-bills-license-plate-reading-tech-and-funded-elections/', '{}'),
  ('00565708-5520-418d-afec-58a295d0d8ec', 'c5ab4eab-702f-49b8-9277-8ea53f3835c6', 'Simmons made history in 2008 as the nation''s first openly gay Black woman elected mayor in New England. She was at Cambridge City Hall in 2004 when Massachusetts became the first state to issue same-sex marriage licenses. Her personal identity and decades-long advocacy for LGBTQ rights — including convening regular forums for LGBTQ+ residents and expanding Cambridge''s sanctuary city declaration to explicitly include transgender and nonbinary individuals (POR 2025 #18, unanimous, March 2025) — place her squarely at full federal recognition and protection for same-sex marriages. Sources: cambridgema.gov/Departments/citycouncil/members/denisesimmons; en.wikipedia.org/wiki/E._Denise_Simmons; cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4644', '{}'),
  ('00565708-5520-418d-afec-58a295d0d8ec', '4e2c69ce-591e-4197-9cd5-7aceff79d390', 'Cambridge unanimously adopted POR 2025 #18 (March 3, 2025) reaffirming the city as sanctuary for immigrants and all marginalized communities including transgender individuals. The council also unanimously passed ORD 2025 #13 (August 2025) clarifying that city employees shall not participate in federal immigration enforcement operations. Simmons voted with these unanimous measures. The policy focuses on not proactively assisting ICE while deporting those with serious criminal records — aligning with only deporting violent offenders and providing de facto legal protection to long-term undocumented residents. Sources: cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4644; cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4745', '{}'),
  ('00565708-5520-418d-afec-58a295d0d8ec', '44905f3b-e105-4f6c-afc7-5d223813dbac', 'Cambridge passed ORD 2025 #13 (August 2025, unanimous) directing city employees not to participate in federal immigration enforcement operations, with CPD required to document ICE actions. POR 2025 #18 (March 2025, unanimous) reaffirmed Cambridge as a sanctuary city. Simmons voted with both. This positions Cambridge as deporting only those who commit serious violent crimes while providing de facto legal protection to long-term undocumented residents with no criminal history. Sources: cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4745; cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4644', '{}'),
  ('00565708-5520-418d-afec-58a295d0d8ec', 'e8dad4a8-eb93-4931-91f5-d8fb5d7dd529', 'Simmons supported POR 2024 #80 (unanimous, June 2024) in support of the Neville Center skilled nursing facility and voted to appropriate $2.5M for Neville Center operations. Cambridge appropriates substantial HUD human services and Cambridge Health Alliance grants annually. As Chair of the Civic Unity Committee she consistently advocates for equitable healthcare access for seniors, low-income, and marginalized residents — aligning with modestly expanding public coverage and community health programs without moving to a fully public system. Sources: cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4482; cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4630', '{}'),
  ('00565708-5520-418d-afec-58a295d0d8ec', 'f1e44d66-5d27-4b51-b54f-b7ace86f6a3c', 'Cambridge unanimously adopted POR 2025 #79 (June 2, 2025) opposing offshore oil and gas drilling expansion. The council approved a Renewable Energy and Greenhouse Gas Reduction revolving fund (CMA 2025 #155), funded Zero Waste Master Plan 2.0 ($97,500), and climate preparedness infrastructure. The council unanimously called for MIT to dissociate from the fossil fuel industry (POR 2024 #122). Simmons voted with these measures. This aligns with rapidly transitioning to renewables and opposing fossil fuel expansion rather than a full emergency declaration. Sources: cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4654; cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4572', '{}'),
  ('00565708-5520-418d-afec-58a295d0d8ec', 'a22215c3-6693-4bc2-b248-01aebba14570', 'Cambridge unanimously adopted POR 2025 #79 (June 2, 2025) in opposition to offshore oil and gas drilling expansion. The council voted unanimously to call for MIT''s dissociation from the fossil fuel industry (POR 2024 #122, September 2024). Simmons voted with both measures. This places her at stopping new permits and opposing expansion but not mandating an immediate ban on all existing extraction. Sources: cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4654; cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4572', '{}'),
  ('00565708-5520-418d-afec-58a295d0d8ec', 'cab61e8a-64fe-4bbd-bc08-fe9914d0091b', 'While Medicare/Medicaid is a federal program, Simmons''s consistent advocacy for expanding community health services — Neville Center ($2.5M appropriation), Cambridge Health Alliance grants, protection of senior meal program funding, and equitable healthcare access for low-income and senior residents — aligns with the Medicare expansion / Medicaid expansion philosophy. No direct federal vote possible at city level but her pattern of healthcare advocacy for vulnerable populations clearly places her at stance 2: expand these programs rather than privatize or cut them. Sources: cambridgema.gov/Departments/citycouncil/members/denisesimmons; cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4482', '{}'),
  ('00565708-5520-418d-afec-58a295d0d8ec', 'd1792200-1d3b-4955-a0b7-0e6980d7a7b2', 'Cambridge unanimously adopted POR 2025 #5 (January 27, 2025) opposing the Congressional SAVE Act, which the council characterized as a voter-suppression measure. Cambridge also authorized in-person early voting (CMA 2025 #178, June 30, 2025). Simmons voted with these unanimous majorities. This aligns with expanding voting access, supporting mail-in and early voting, and opposing restrictive photo ID requirements. Sources: cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4632; cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4658', '{}'),
  ('00565708-5520-418d-afec-58a295d0d8ec', 'c1ac1330-47f7-44ec-baf3-c913d926b97c', 'Cambridge adopted POR 2025 #105 (June 30, 2025) directing Human Services Committee oversight of the Cambridge Preschool Program — a publicly subsidized universal preschool initiative. Cambridge also funded Rise Up Cambridge and its successor municipal voucher program (POR 2025 #73, 8-1; POR 2025 #69, unanimous) providing direct economic support to low- and middle-income families. Simmons chairs the Civic Unity Committee and has consistently advocated for equitable family and youth services. This aligns with significantly expanding subsidies for low- and middle-income families. Sources: cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4658; cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4652', '{}'),
  ('00565708-5520-418d-afec-58a295d0d8ec', 'ba59337e-30e2-4aba-a39a-426b3366eb27', 'Simmons exercised a charter right (POR 2024 #70, June 2024) to delay the Mass Avenue reconstruction to protect small businesses — showing she weighs economic impact alongside transportation improvements. The council she votes with has invested in the Grand Junction Multiuse Path (POR 2025 #4), MBTA safety improvements (POR 2025 #19), EV charging permits, bike infrastructure, and pedestrian safety audits. Cambridge eliminated parking minimums. Her approach balances roads with multimodal options and bike/pedestrian safety, aligning with stance 2. Sources: cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4481; cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4644', '{}'),
  ('00565708-5520-418d-afec-58a295d0d8ec', 'eb3d1247-0de1-4b7f-baec-7259861efd53', 'Simmons supported POR 2025 #49 (unanimous, April 2025) inviting the Harvard Square property owner before the Economic Development Committee for vacant property accountability — targeted oversight rather than blanket incentives. She championed wage fairness ordinances for city janitors, cannabis equity for minority entrepreneurs (ORD 2024 #4, 6-2), and Community Benefits Ordinance amendments (POR 2025 #96). Her Mass Ave charter right reflects small business protection. She voted 9-0 on BioMed lab rezoning with $20M in community benefits conditions. This aligns with targeted incentives tied to community benefit requirements. Sources: cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4648; cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4482; cambridgema.gov/Departments/citycouncil/members/denisesimmons', '{}'),
  ('00565708-5520-418d-afec-58a295d0d8ec', '4938766b-b45a-46e3-93bd-b8b30651271a', 'Simmons has a fiscally moderate record on homelessness services. In April 2025 she supported closing a homeless shelter on fiscal grounds. In May 2025 she led a substitute budget order that preserved emergency housing vouchers for 172 people at imminent risk while cutting general shelter and basic income funding, calling inaction a ''moral failure'' — but still making cuts. Cambridge funded $1M housing vouchers (CMA 2025 #158) and HUD grants for services. Her approach allows enforcement when services exist but emphasizes targeted housing vouchers over broad shelter expansion, aligning with stance 3: enforcement only when adequate shelter is available, with citations diverting to services. Sources: cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4656; cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4649', '{}'),
  ('00565708-5520-418d-afec-58a295d0d8ec', '7687de4f-4d0b-462a-b803-bdfb23b16b42', 'Cambridge funded Zero Waste Master Plan 2.0 ($97,500, March 2025), a $6,000 DEP waste-reduction grant (January 2025), POR 2024 #128 (September 2024) directing the City Manager to address leaking DPW garbage trucks, and a MassDEP Universal Waste Shed grant ($5,000, March 2025). Simmons voted with these unanimous sanitation measures. Cambridge''s approach treats poor sanitation as a services-delivery failure requiring increased capacity and equitable community access, aligning with stance 2. Sources: cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4577; cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4645', '{}'),
  ('00565708-5520-418d-afec-58a295d0d8ec', '1935979c-b290-42e4-baa5-8cb0138b4ffa', 'Cambridge adopted Zero Waste Master Plan 2.0 (POR 2025 #41, March 2025), Floodplain Zoning Amendments (CMA 2025 #72), banned second-generation anticoagulant rodenticides on city properties (POR 2025 #90, June 2025, unanimous), funded extreme heat response community engagement ($100K), and approved a Renewable Energy revolving fund. Simmons voted with these measures. Cambridge''s development approval framework requires environmental review and community benefits before development approval. This places her at stance 2: protecting existing green space and requiring developers to fully offset environmental impacts. Sources: cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4647; cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4656', '{}'),
  ('00565708-5520-418d-afec-58a295d0d8ec', 'c308e8e8-caac-44f5-ab04-dbfecf40bbe2', 'Simmons chairs the Housing Committee and led passage of the Affordable Housing Overlay, doubled mandatory affordable units, and tripled developer linkage fees. Cambridge adopted POR 2025 #24/26 (broker-fee elimination, 7-1, March 2025), POR 2025 #21 (Affordable Rent Incentive Program with tax abatements), and POR 2025 #37 (eviction record sealing outreach). This layered approach — beyond just protecting new construction — aligns with strengthening existing tenant protections and extending coverage, consistent with stance 2. Sources: cambridgema.gov/Departments/citycouncil/members/denisesimmons; cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4644', '{}'),
  ('00565708-5520-418d-afec-58a295d0d8ec', 'c267e137-0ff9-4e7d-9d13-e3cea1756cd0', 'Cambridge adopted POR 2025 #77 (May 19, 2025) supporting clean slate legislation (HD 1811/SD 1114, HD 1693/SD 1124) for criminal record expungement and POR 2025 #75 declaring a Day of Reflection on Mass Incarceration. The council consistently funds diversion and rehabilitation programs via HUD grants. Simmons chairs Civic Unity Committee focused on fairness in the justice system. Note: she also voted YES on $570K in police weapons (April 2025) — she is not anti-enforcement. Her record overall aligns with stance 2: reducing incarcerated population through diversion and bail reform rather than building new jail capacity. Sources: cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4653; cambridgema.iqm2.com/Citizens/Detail_Meeting.aspx?ID=4648', '{}'),
  ('ad060f52-145c-41e3-8bd1-c454ac1ed46c', '92730f69-ae57-401c-8ad1-2d07834a895d', 'Sobrinho-Wheeler''s signature issue is public financing of elections. The 2025 Cambridge City Council election guide states he advocates for ''public financing of municipal elections and working toward citizen-funded elections statewide.'' Aligns with stance 1: ban all private money and publicly fund campaigns.', '{}'),
  ('ad060f52-145c-41e3-8bd1-c454ac1ed46c', '4938766b-b45a-46e3-93bd-b8b30651271a', 'When Cambridge conceded to closing a 58-bed shelter in April 2025, Sobrinho-Wheeler said the council''s disagreement with the administration ''comes down to a difference between no, but and yes, and,'' advocating for expanding services rather than simply accepting constraints. He directed focus toward a $5M Federal Funding Stabilization Fund to expand alternative services. Aligns with stance 2: decriminalizing public sleeping while investing in shelter capacity and voluntary service connections.', '{}'),
  ('ad060f52-145c-41e3-8bd1-c454ac1ed46c', '4e2c69ce-591e-4197-9cd5-7aceff79d390', 'Sobrinho-Wheeler voted yes on Cambridge''s welcoming community ordinance (July 2025) barring city cooperation with ICE, and co-sponsored February 2026 measures unanimously codifying the ICE response including a ban on ICE operations on city property and a hiring ban on former ICE/CBP/HSI agents. He stated the goal was ''protecting residents.'' Consistent with stance 2: significantly expand legal pathways while barring local cooperation with enforcement.', '{}'),
  ('ad060f52-145c-41e3-8bd1-c454ac1ed46c', '44905f3b-e105-4f6c-afc7-5d223813dbac', 'At the February 2026 Cambridge City Council meeting, Sobrinho-Wheeler stated: ''The violence that ICE is perpetrating has nothing to do with law enforcement,'' and co-sponsored an ordinance banning ICE operations on city property and blocking city employees from assisting ICE. He also proposed barring former ICE/CBP/HSI agents from joining the Cambridge Police. Aligns with stance 2: only deport those who commit serious violent crimes while protecting others.', '{}'),
  ('ad060f52-145c-41e3-8bd1-c454ac1ed46c', 'c5ab4eab-702f-49b8-9277-8ea53f3835c6', 'In November 2024, Sobrinho-Wheeler explicitly challenged the reappointment of an advisory board member, stating: ''I''m disappointed in this appointment. Mr. Winters has a history of anti-LGBT and anti-Muslim posts on social media that councillor Azeem and others have documented in the past that I don''t believe he''s ever apologized for.'' He framed public accountability for anti-LGBT conduct as essential civil rights protection. As a DSA member, his platform includes full federal protections for LGBTQ individuals. Aligns with stance 1: require all states to recognize same-sex marriages with full federal benefits.', '{}'),
  ('ad060f52-145c-41e3-8bd1-c454ac1ed46c', 'f7e5678d-dadd-4556-a2fc-446e24642ceb', 'Sobrinho-Wheeler is a DSA member who framed his political mission as ''fighting for democracy not just in our political system, not just at the ballot box, but in our economy.'' He has explicitly opposed austerity, stating ''I would push back strongly on any effort to implement austerity or really cut services,'' and supported expanding the Rise Up Cambridge cash assistance program and social housing. He advocates exploring ''all options'' to fund social programs. Aligns with stance 1: significantly raise taxes on wealthy individuals and large corporations.', '{}'),
  ('ad060f52-145c-41e3-8bd1-c454ac1ed46c', 'c1ac1330-47f7-44ec-baf3-c913d926b97c', 'Between council terms, Sobrinho-Wheeler served as New England progressive governance director for the Working Families Party, where he drafted legislation on affordable housing, childcare, and sustainability. His DSA-aligned platform supports expanding publicly funded social services. Aligns with stance 2: significantly expanding subsidies and provider grants to make childcare affordable for low- and middle-income families.', '{}'),
  ('ad060f52-145c-41e3-8bd1-c454ac1ed46c', 'f1e44d66-5d27-4b51-b54f-b7ace86f6a3c', 'Cambridge''s September 2025 council agenda included a Zero Emissions Transportation Plan to ''end fossil-fuel transportation emissions in the city by 2050,'' renewable energy labor standards, and solar panel access protections — all items Sobrinho-Wheeler''s progressive bloc supported. He was the lead sponsor of the social housing bill, which he framed as part of a ''paradigm shift'' away from commodification, consistent with climate-aligned urbanism. Aligns with stance 2-3; best fit is 2 given council-wide rapid transition commitment and his progressive leadership role.', '{}'),
  ('ad060f52-145c-41e3-8bd1-c454ac1ed46c', 'a22215c3-6693-4bc2-b248-01aebba14570', 'Cambridge''s 2025 council agenda included a Zero Emissions Transportation Plan to end fossil-fuel transportation emissions by 2050 and renewable energy labor standards. Sobrinho-Wheeler, as a DSA progressive bloc leader, supported this agenda. His Working Families Party background involved drafting sustainability legislation. Aligns with stance 2: stop issuing new permits for fossil fuel drilling/expansion.', '{}'),
  ('ad060f52-145c-41e3-8bd1-c454ac1ed46c', 'c267e137-0ff9-4e7d-9d13-e3cea1756cd0', 'Sobrinho-Wheeler''s public safety record consistently favors services over enforcement. He voted against police surveillance tech (6-3 vote, Feb 2025), challenged police firearms mandates, questioned arming school resource officers, and opposed a police settlement saying ''fundamental issues with the police department are never addressed.'' His ''yes and'' framing on homelessness services mirrors a diversion approach. Aligns with stance 2: reducing the incarcerated population through pretrial diversion, bail reform, and treatment alternatives rather than building new capacity.', '{}'),
  ('ad060f52-145c-41e3-8bd1-c454ac1ed46c', '7687de4f-4d0b-462a-b803-bdfb23b16b42', 'Sobrinho-Wheeler co-sponsored the March 2026 ''snow corps'' initiative and was quoted highlighting how the current system creates a ''patchwork'' disproportionately affecting residents with mobility challenges, making the case for expanded city sanitation services for underserved areas. Aligns with stance 2: increase sanitation crews and prioritize historically underserved neighborhoods to equalize service citywide.', '{}'),
  ('ad060f52-145c-41e3-8bd1-c454ac1ed46c', '1935979c-b290-42e4-baa5-8cb0138b4ffa', 'Sobrinho-Wheeler''s council work includes environmental integration: he authored the social housing bill framing housing as a public good over speculation, supported Zero Emissions Transportation Plan items, and his WFP background included drafting sustainability legislation. Consistent with protecting parks/tree canopy and requiring developers to offset environmental impact. Aligns with stance 2: protect existing parks and tree canopy strictly; require developers to fully offset any environmental impact.', '{}'),
  ('af870d90-718a-4d0c-a267-8436e84720ba', 'd4f18138-a2e0-4110-b925-7387d9d0d16d', 'Huang''s administration has pursued broad upzoning: the 100% Affordable Housing Overlay (AHO) allows denser development city-wide for all-affordable projects, and the city''s planning arm has championed citywide multifamily reforms allowing four-story buildings by right across all residential zones. Central Square rezoning study (2024) proposed up to 18-22 story buildings in the commercial core with density bonuses for retail and cultural space. Sources: cambridgema.gov/CDD (AHO), cambridgeday.com development archives page 8 (four-story multifamily landmark reform), cambridgeday.com July 2024 Central Square rezoning article.', '{}'),
  ('af870d90-718a-4d0c-a267-8436e84720ba', '669cac97-66a6-4087-b036-936fbe62efb3', 'Huang has allocated over $400M toward affordable housing through FY26 (4,100+ units preserved or created), with FY27 proposing $51M+ including a new social housing development program. The FY25 budget dedicated $47M to affordable housing and $16M to unhoused residents. The administration uses AHO, Affordable Housing Trust, inclusionary zoning, and now a social housing pilot to expand below-market units at scale. Sources: cambridgema.gov FY25 budget news, cambridgema.gov FY27 budget news (April 2026), cambridgeday.com April 29 2026 billion-dollar budget article.', '{}'),
  ('af870d90-718a-4d0c-a267-8436e84720ba', 'ba59337e-30e2-4aba-a39a-426b3366eb27', 'Cambridge under Huang explicitly prioritizes pedestrians, cyclists, and transit over automobiles, with ~30% of households car-free. The city operates a Complete Streets program, Vision Zero initiative, dedicated bike infrastructure, and the Department of Transportation merged with CDD''s Transportation Planning in April 2025 to better integrate multimodal planning. FY25 budget allocated $33M for Vision Zero/traffic safety. Sources: cambridgema.gov Getting Around Cambridge page, cambridgema.gov FY25 budget announcement, cambridgema.gov Department of Transportation overview.', '{}'),
  ('af870d90-718a-4d0c-a267-8436e84720ba', 'e9ebefcd-c496-45e8-b816-a79f8442ba85', 'Huang established the 911 Clinician program in the Emergency Communications Center (2023) for mental health crisis diversion, and launched an unarmed care response pilot (CARESS-style). A Public Safety Task Force (pre-Huang, 2021) set the reform framework; the unarmed care team handled ~45% of eligible calls in its first year (reported April 2025). Police funding has been maintained while adding layered crisis response rather than reallocating away from law enforcement. Sources: cambridgema.gov 911 Clinician page, cambridgeday.com April 2025 archive (unarmed care team first year), cambridgema.gov Public Safety Task Force documents.', '{}'),
  ('af870d90-718a-4d0c-a267-8436e84720ba', '6fbf39ae-6b19-4182-b4c2-6a8d25c86c0f', 'Huang''s FY27 budget allocates ~$16M for homelessness and housing stability, with shelter (Winter Warming Center, Multi-Service Center), outreach workers, and eviction prevention as core tools. April 2025 reporting noted the Transition Wellness Center shelter faced uncertain future while other social services were expanded. The city''s model emphasizes services and housing stability first, with enforcement not the primary tool. Sources: cambridgema.gov DHSP page, cambridgeday.com April 15 2025 archive (shelter uncertainty), cambridgeday.com April 29 2026 (FY27 $16M homelessness line).', '{}'),
  ('af870d90-718a-4d0c-a267-8436e84720ba', '0bc588c6-39e1-4084-b5de-cac909b8b762', 'Huang maintains an Interactive Equity and Inclusion Dashboard tracking workforce diversity and pay equity city-wide, operates the Civic Unity Committee fostering equity across race/gender/orientation, and dedicates over $17M per year to economic opportunity programs for historically marginalized communities (FY26 budget). The administration frames equity as central to operations but does not mandate racial equity requirements in all private institutions — this is active systemic enforcement within city government plus community investment. Sources: cambridgema.gov Equity and Inclusion Dashboard, cambridgema.gov FY26 budget announcement, cambridgema.gov Civic Unity Committee page.', '{}'),
  ('af870d90-718a-4d0c-a267-8436e84720ba', 'eb3d1247-0de1-4b7f-baec-7259861efd53', 'Cambridge''s Economic Opportunity and Development Division focuses on small business support (Storefront Improvement Program, E-Commerce grants, Legacy Business Awards), the innovation/biotech economy in Kendall Square, and commercial district revitalization — without large corporate tax abatements. The FY26 budget explicitly targets ''economic opportunity particularly for historically marginalized communities.'' The city uses targeted incentives and community benefit requirements rather than maximum incentives for any large employer. Sources: cambridgema.gov CDD Economic Opportunity page, cambridgema.gov FY26 budget announcement.', '{}'),
  ('af870d90-718a-4d0c-a267-8436e84720ba', 'b9ccee94-ad96-4f10-b655-889d8e5abe92', 'Cambridge operates as a ''welcoming community'' with protections limiting local police cooperation with ICE. In July 2025 the council advanced a revision to the welcoming community law ahead of a council vote to strengthen it. City Council also codified emergency response procedures for ICE operations (per Cambridge Day city council archives, page 2). The April 2025 coverage confirmed Cambridge Housing Authority and city officials took active steps to protect undocumented residents from immigration enforcement. No evidence Yi-An Huang directed police to proactively assist ICE. Sources: cambridgeday.com city-council archives page 2, cambridgeday.com July 2025 archive.', '{}'),
  ('af870d90-718a-4d0c-a267-8436e84720ba', 'c308e8e8-caac-44f5-ab04-dbfecf40bbe2', 'Massachusetts state law (Chapter 40P, enacted 1994) prohibits municipal rent control, so Cambridge cannot impose rent stabilization. Huang''s administration works within this constraint, relying on the Affordable Housing Overlay, inclusionary zoning requirements, tenant rights ordinances (Tenants Rights and Resources Ordinance, 2020), and direct affordable housing subsidies rather than price controls. No evidence Yi-An Huang has advocated for rent control legislation or sought state enabling authority. The administration maintains current tenant protections while allowing market rents on new construction. Sources: cambridgema.gov CDD Housing for Renters page, cambridgema.gov CDD Housing Development page.', '{}'),
  ('af870d90-718a-4d0c-a267-8436e84720ba', '1935979c-b290-42e4-baa5-8cb0138b4ffa', 'Huang''s budgets have consistently prioritized climate: FY25 allocated $21M for climate resilience and $17M for net-zero programs, plus created a Chief Climate Officer position and Office of Sustainability. The city enforces mandatory green building requirements (Article 22), a Building Energy Disclosure Ordinance, and has a carbon neutrality by 2050 goal. These are regulatory requirements placed on developers, not just voluntary standards. Sources: cambridgema.gov FY25 budget announcement, cambridgema.gov Climate Change Planning page, cambridgema.gov CDD Zoning and Development (Article 22 green building requirements).', '{}'),
  ('af870d90-718a-4d0c-a267-8436e84720ba', 'fb25c1ac-91cc-49bf-8afc-c7fa22ef45e4', 'Huang''s administration has actively promoted growth: the city set a 12,500-unit housing goal, championed Central Square rezoning (up to 18-22 stories), supported citywide multifamily upzoning (4-story by right everywhere), and the assistant city manager identified city-owned lots as the ''biggest opportunity'' for redevelopment. The FY27 budget expressed concern about declining development activity and falling commercial property values, signaling a preference for more development not less. Permitting is streamlined; infrastructure investment is proactive. Sources: cambridgeday.com July 2024 Central Square rezoning, cambridgema.gov FY27 budget news, cambridgeday.com April 29 2026 billion-dollar budget.', '{}'),
  ('e44fdba7-5fd0-43c2-a125-c999b0a0bb97', 'f1e44d66-5d27-4b51-b54f-b7ace86f6a3c', 'Zusy expressed concern about Cambridge''s BEUDO electrification mandate, saying the timeline is too tight: ''I worry about Beudo because the timeline is too tight...if Eversource can''t even provide the electricity by 2035, should we demand that everything is electrified by 2035?'' She supports community geothermal and sustainability goals but takes a data-first and fiscally cautious approach. On solar zoning she stated: ''We have to have a balanced view. We do want to build housing, but we also have sustainability goals. Balance is key.''', '{"https://www.cambridgeday.com/2023/10/catherine-zusy-for-city-council-2023/","https://www.cambridgeday.com/2025/10/higher-cambridge-construction-fees-get-a-study-and-council-deals-with-park-safety-solar-zoning/"}'),
  ('e44fdba7-5fd0-43c2-a125-c999b0a0bb97', 'a22215c3-6693-4bc2-b248-01aebba14570', 'No direct statement on fossil fuel drilling policy. Zusy''s climate approach is cautious and pragmatic — skeptical of aggressive mandates, supportive of sustainability goals but deferential to market and infrastructure realities. Her ''balanced view'' framing on housing vs. sustainability and skepticism of the 2035 electrification deadline reflects a maintain-current-regulations stance rather than expand or restrict.', '{"https://www.cambridgeday.com/2023/10/catherine-zusy-for-city-council-2023/"}'),
  ('e44fdba7-5fd0-43c2-a125-c999b0a0bb97', '1935979c-b290-42e4-baa5-8cb0138b4ffa', 'Zusy consistently applies a ''balance'' lens to environmental policy vs. development tradeoffs. On solar zoning: ''What I propose is that we ask for more data … before we have CDD start writing zoning language, because I think we are data deficient.'' She favors consistent environmental standards with developer flexibility, and has personal history revitalizing Magazine Beach Park — a practical conservationist rather than a strict preservationist.', '{"https://www.cambridgeday.com/2025/10/higher-cambridge-construction-fees-get-a-study-and-council-deals-with-park-safety-solar-zoning/","https://www.cambridgema.gov/Departments/citycouncil/members/catherinezusy"}'),
  ('e44fdba7-5fd0-43c2-a125-c999b0a0bb97', '4938766b-b45a-46e3-93bd-b8b30651271a', 'Zusy supports shelter/service investment but is cost-conscious: cited $18,500 per resident cost at First Church Shelter vs. $52,000 at Transition Wellness Center and said ''I want us to learn from the Transitional Wellness Center, because I think those wraparound services really provide support.'' She backed a $5M stabilization fund but emphasized value comparison. Her approach reflects service-investment with enforcement where shelter is unavailable — a middle position.', '{"https://www.cambridgeday.com/2025/04/council-concedes-to-closing-a-homeless-shelter-while-bulking-up-services/"}'),
  ('e44fdba7-5fd0-43c2-a125-c999b0a0bb97', 'e9ebefcd-c496-45e8-b816-a79f8442ba85', 'Zusy scrutinized police department budget requests, calculated officer-per-capita ratios across municipalities to question whether Cambridge overstaffs, and asked why replacement firearms cost more than twice as much as prior purchases. She is not a defund advocate but applies the same fiscal discipline she uses elsewhere to police spending. The CARE unarmed response team continues with council support (she did not oppose). Her approach is current funding plus oversight.', '{"https://www.cambridgeday.com/2025/03/answers-expected-on-police-request-for-new-guns-are-delayed-again-until-mondays-council-meeting/"}'),
  ('e44fdba7-5fd0-43c2-a125-c999b0a0bb97', 'eb3d1247-0de1-4b7f-baec-7259861efd53', 'Zusy emphasizes fiscal responsibility as her primary lens: ''The city should reserve its money for increasingly tighter times.'' She was skeptical of spending on Bluebike stations and entertainment venue studies. Endorsed by Cambridge Citizens Coalition rather than pro-business or pro-labor slates. Her approach favors targeted incentives with accountability requirements rather than broad corporate subsidies or maximum incentive packages.', '{"https://www.cambridgeday.com/2025/10/cambridge-city-council-election-guide-2025/"}'),
  ('e44fdba7-5fd0-43c2-a125-c999b0a0bb97', 'ba59337e-30e2-4aba-a39a-426b3366eb27', 'Zusy is a cyclist who supports separated bike lanes but ''called to slow bike lane installation until parking alternatives are in place.'' She is interested in ''solving larger regional transportation issues'' and ensuring safety for all modes. Her 2023 campaign said she would not pre-commit to specific timelines. Cambridge Bicycle Safety listed her as a ''supporter'' and endorsed her in 2025. Her approach maintains roads while adding multimodal improvements where feasible.', '{"https://www.cambridgeday.com/2025/10/cambridge-city-council-election-guide-2025/","https://www.cambridgeday.com/2024/09/zusy-is-elected-to-cambridges-city-council-filling-surprise-vacancy-for-a-monday-start/"}'),
  ('e44fdba7-5fd0-43c2-a125-c999b0a0bb97', 'fb25c1ac-91cc-49bf-8afc-c7fa22ef45e4', 'Zusy was the lone dissenting vote (8-1) against Cambridge''s landmark four-plus-two multifamily zoning ordinance in February 2025. She consistently opposed citywide upzoning, favoring density concentrated in squares and transit corridors per the Envision Cambridge comprehensive plan: ''There are different ways to build more housing than a multifamily ordinance.'' Critics of the decision said she took issue with specifics and advocated starting the process over. She is the slowest-growth voice on the council.', '{"https://www.cambridgeday.com/2025/02/in-landmark-zoning-reform-cambridge-votes-to-legalize-four-story-multifamily-homes-citywide/","https://www.cambridgeday.com/2025/01/rejection-of-three-story-zoning-plan-paves-way-for-passage-of-four-story-residential-in-february/","https://www.cambridgeday.com/2025/10/affordable-housing-ideas-abound-at-cambridge-candidates-forum/"}')
